async function genPreflight(flt) {
  const msgs = [];
  const dep = flt.dep || '????', arr = flt.arr || '????';
  const sbUser = roster[flt.callsign];
  if (sbUser) {
    try {
      const o = await simbriefOfp(sbUser);
      const unit = o.params?.units === 'lbs' ? 'LBS' : 'KG';
      const n = v => Number(v || 0).toLocaleString('en-US');
      if (o.times?.est_time_enroute) flt._sbEet = Math.round(Number(o.times.est_time_enroute) / 60);
      msgs.push({ id: 'loadsheet', label: 'LOADSHEET', body: [
        `=== LOADSHEET ${flt.callsign} ===`,
        `${o.origin?.icao_code || dep}/${o.destination?.icao_code || arr} ALT:${o.alternate?.icao_code || 'N/A'}`,
        `ACFT:${o.aircraft?.icaocode || '?'} CI:${o.general?.costindex || '?'}`,
        `PAX:${o.weights?.pax_count || 0} CARGO:${n(o.weights?.cargo)}${unit}`,
        `ZFW:${n(o.weights?.est_zfw)} TOW:${n(o.weights?.est_tow)} LDW:${n(o.weights?.est_ldw)} ${unit}`,
        `FUEL BLK:${n(o.fuel?.plan_ramp)} TRIP:${n(o.fuel?.enroute_burn)} RSV:${n(o.fuel?.reserve)} ${unit}`,
      ].join('\n') });
    } catch (e) { log(`SimBrief ${flt.callsign}: ${e.message}`, 'wrn'); }
  }
  try { const tech = await opsTechStatusMessage(flt); if (tech) msgs.push(tech); } // 5.2: TechLog (solo tu vuelo)
  catch (e) { log(`TechLog ${flt.callsign}: ${e.message}`, 'wrn'); }
  try {
    const icaos = [dep, arr].filter(x => x !== '????');
    if (icaos.length) {
      const [m, t, atis] = await Promise.all([NBV.wx.metar(icaos, 2), NBV.wx.taf(icaos).catch(() => ''), dep !== '????' ? atisText(dep) : '']);
      msgs.push({ id: 'wx_brief', label: 'WX BRIEF', body: `=== WX BRIEFING ${flt.callsign} ===\n${dep}→${arr}\n${atis ? atis + '\n' : ''}METAR:\n${m || 'N/A'}\nTAF:\n${(t || 'N/A').substring(0, 400)}` });
    }
  } catch (e) { log(`WX ${flt.callsign}: ${e.message}`, 'wrn'); }
  return msgs;
}

async function genEnroute(flt) {
  const arr = flt.arr || '????';
  const msgs = [];
  try {
    const data = await NBV.ivao.get();
    const t = NBV.ivao.traffic(data, arr);
    let traf = `=== TRAFFIC ${arr} ===\n${t.density} (ARR:${t.arriving.length} DEP:${t.departing.length})\n`;
    for (const p of t.arriving.slice(0, 6)) {
      traf += `${p.callsign || '?'} ${safeStr(p.flightPlan?.aircraftId) || '?'} FROM ${NBV.ivao.depOf(p) || '?'} GS${safeNum(p.lastTrack?.groundSpeed)} FL${Math.round(safeNum(p.lastTrack?.altitude) / 100)}\n`;
    }
    const atc = NBV.ivao.atcFor(data, arr);
    traf += atc.length ? `ATC: ${atc.map(a => `${a.callsign} ${fmtFreq(a.atcSession?.frequency)}`).join(', ')}\n` : `NO ATC ONLINE ${arr}\n`;
    msgs.push({ id: 'traffic', label: 'TRAFFIC', body: traf });
  } catch (e) { log(`Traffic ${flt.callsign}: ${e.message}`, 'wrn'); }
  try {
    const m = await NBV.wx.metarLatest(arr);
    if (m) msgs.push({ id: 'wx_enroute', label: 'WX ENRTE', body: `=== WX EN-ROUTE ${flt.callsign} ===\nDEST ${arr} METAR:\n${m}` });
  } catch (e) {}
  return msgs;
}

async function genDescent(flt) {
  const arr = flt.arr || '????';
  const msgs = [];
  try {
    const [atis, metar] = await Promise.all([atisText(arr), NBV.wx.metarLatest(arr).catch(() => '')]);
    msgs.push({ id: 'arrival_info', label: 'ARR INFO', body: `=== ARRIVAL INFO ${flt.callsign} ===\n${arr}\n${atis ? atis + '\n' : ''}METAR:\n${metar || 'N/A'}` });
  } catch (e) { log(`Descent WX ${flt.callsign}: ${e.message}`, 'wrn'); }
  try {
    const data = lastIvaoData || NBV.ivao.last();
    if (data) {
      const t = NBV.ivao.traffic(data, arr);
      const destAtc = NBV.ivao.atcFor(data, arr);
      const hasApp = destAtc.some(a => NBV.ivao.posOf(a) === 'APP');
      if (t.total > 8 && destAtc.length > 0) {
        let warn = `=== ATC ADVISORY ${arr} ===\n`;
        if (t.total > 12) warn += `TRAFICO MUY ALTO - ${t.total} ACFT (${t.arriving.length} ARR/${t.departing.length} DEP)\nPOSIBLE ATC DELAY EN LLEGADA\nEspere vectores extendidos o holdings.\n`;
        else warn += `TRAFICO ALTO - ${t.total} ACFT (${t.arriving.length} ARR/${t.departing.length} DEP)\nPOSIBLE SECUENCIACION EN LLEGADA\n`;
        if (hasApp) warn += `APP activo — secuenciacion probable.\n`;
        warn += `ATC: ${destAtc.map(a => a.callsign).join(', ')}\n`;
        msgs.push({ id: 'atc_delay', label: 'ATC ADVSY', body: warn });
        discordNotifyAlert(flt.callsign, 'ATC CONGESTION', `${arr}: ${t.total} aeronaves (${t.arriving.length} ARR/${t.departing.length} DEP)`);
      }
    }
  } catch (e) { log(`ATC check ${flt.callsign}: ${e.message}`, 'wrn'); }
  const connMsg = genPaxConnections(arr);
  if (connMsg) msgs.push({ id: 'pax_conn', label: 'PAX CONN', body: connMsg });
  return msgs;
}

