function updateDashboard() {
  const dash = $('dashboard');
  const activeFlights = Object.values(flights).filter(f => !f.offlineSince);
  if (activeFlights.length === 0) {
    const run = !!monitorInterval;
    dash.innerHTML = `<div class="dash-empty" id="dashEmpty">${NBV.ui.icon('radar', 'big')}
      <b>${run ? 'Escuchando la frecuencia' : 'La torre está en silencio'}</b>
      <p>${run ? `Aún no hay vuelos ${esc(($('cA')?.value || 'NBV').toUpperCase())} conectados a IVAO. En cuanto un piloto conecte aparecerá aquí y recibirá su bienvenida automáticamente.` : 'Inicia el monitor para detectar los vuelos de AirNubeiro en IVAO y enviarles meteo, tráfico y loadsheet en cada fase.'}</p>
      ${run ? '' : `<button type="button" class="btn-pri" data-click="toggleMonitor">${NBV.ui.icon('play')}Iniciar monitor</button>`}</div>`;
    return;
  }
  const order = { PREFLIGHT: 0, ENROUTE: 1, DESCENT: 2, LANDED: 3 };
  activeFlights.sort((a, b) => (order[a.phase] ?? 9) - (order[b.phase] ?? 9));
  const PH = { PREFLIGHT: 'Preflight', ENROUTE: 'En ruta', DESCENT: 'Descenso', LANDED: 'En tierra' };
  const ST = { sent: 'enviado — esperando a que el avión lo recoja', delivered: 'entregado al avión', held: 'retenido: el avión no está conectado a Hoppie — clic para enviar', sending: 'enviando', pending: 'pendiente — clic para enviar', error: 'error — clic para reintentar' };

  dash.innerHTML = activeFlights.map(f => {
    NBV.ui.stats.seen(f.callsign);
    const ph = String(f.phase || '').toLowerCase();
    const pct = f.phase === 'LANDED' ? 100 : Math.max(0, Math.min(100, Math.round(f.progressPct || 0)));
    const e = etaInfo({ arrivalDist: f.arrivalDist, gs: f.gs, lat: f.lat, lon: f.lng, arr: f.arr });
    const d = [];
    d.push(['ALT', f.alt > 0 ? 'FL' + Math.round(f.alt / 100) : f.onGround ? 'GND' : '—']);
    d.push(['GS', f.gs > 0 ? f.gs + ' kt' : '—']);
    if (e.eta && f.phase !== 'LANDED') d.push(['ETA', e.eta]);
    if (e.dist != null) d.push(['DEST', e.dist + ' nm']);
    if (f.estEnrouteMin > 0) d.push(['EET', `${Math.floor(f.estEnrouteMin / 60)}h${String(Math.round(f.estEnrouteMin % 60)).padStart(2, '0')}`]);
    if (f.enrouteStart) d.push(['ENR', Math.round((Date.now() - f.enrouteStart) / 60000) + ' min']);
    if (f.ivaoState) d.push(['ST', f.ivaoState]);
    if (f.routeInfoCount > 0) d.push(['RI', '×' + f.routeInfoCount]);
    const msgs = Object.entries(f.msgStatus || {}).map(([key, s]) => {
      const label = esc(key.replace(/_/g, ' ').toUpperCase());
      const ic = s === 'delivered' ? NBV.ui.icon('check') : s === 'sent' ? NBV.ui.icon('clock') : s === 'error' ? NBV.ui.icon('refresh') : (s === 'pending' || s === 'held') ? NBV.ui.icon('send') : '';
      const tip = s === 'delivered' && f.msgDelivered?.[key] ? `entregado al avión ${f.msgDelivered[key]}` : ST[s] || s;
      return (s === 'pending' || s === 'error' || s === 'held')
        ? `<button type="button" class="flt-msg ${s}" title="${label}: ${esc(tip)}" data-click="manualSend|${esc(f.callsign)}|${esc(key)}">${ic}${label}</button>`
        : `<span class="flt-msg ${esc(s)}" title="${label}: ${esc(tip)}">${ic}${label}</span>`;
    }).join('');
    const src = f.srcSim ? ['src-sim', 'SIM'] : f.srcPhpvms ? ['src-phpvms', 'phpVMS'] : ['src-ivao', 'IVAO'];
    const meta = [esc(f.aircraft || ''), f.registration ? esc(f.registration) : '', [f.pilotIdent, f.pilotName].filter(Boolean).map(esc).join(' · ')].filter(Boolean);
    { const ac = NBV.acars.to(f.callsign); if (ac !== String(f.callsign).toUpperCase()) meta.push(`ACARS ${esc(ac)}`); }
    if (f.tech) { // 5.2: TechLog de tu avión
      const t = f.tech, nDef = (t.deferred?.length || 0) + (t.open?.length || 0), bad = t.dispatch !== 'GO' || /NOT/.test(t.ready) || f.techMismatch;
      meta.push(`<b class="${bad ? 'tech-bad' : 'tech-ok'}" title="TechLog: ${esc(t.reg)}${f.techMismatch ? ' ≠ ' + esc(f.registration) : ''}">TECH ${esc(t.dispatch)} · ${esc(t.ready)}${nDef ? ` · ${nDef} def.` : ''}${f.techMismatch ? ' · LIVERY ' + esc(t.reg) : ''}</b>`);
    }
    const cs = esc(f.callsign);
    const click = NBV.ui.embed ? ` data-cs="${cs}" tabindex="0" role="button" aria-label="${cs}: escribir un mensaje" data-click="opsCompose|${esc(cs)}" data-keydown="opsCompose|${esc(cs)}" data-key="Enter"` : '';
    return `<article class="flt-card ph-${esc(ph)}"${click}>
      <div class="fc-top"><div class="flt-cs">${cs}</div>${NBV.ui.embed ? `<span class="fc-cmp">${NBV.ui.icon('pen')}Escribir</span>` : ''}<span class="flt-phase ${esc(ph)}">${PH[f.phase] || esc(f.phase)}</span></div>
      <div class="fc-route"><span class="ap">${esc(f.dep || '----')}</span><div class="fc-bar"><i style="width:${pct}%"></i><svg class="ic" style="left:${pct}%" aria-hidden="true"><use href="#i-plane"/></svg></div><span class="ap">${esc(f.arr || '----')}</span></div>
      <div class="flt-data">${d.map(([k, v]) => `<div class="flt-d">${k} <span>${esc(String(v))}</span></div>`).join('')}</div>
      <div class="fc-meta">${meta.map(m => `<span>${m}</span>`).join('<span class="sep"></span>')}<span class="${src[0]}" style="margin-left:auto">${src[1]}</span></div>
      ${msgs ? `<div class="flt-msgs">${msgs}</div>` : ''}
    </article>`;
  }).join('');
}

