// ══════════════════════════════════════════════════════════════════
//  INTEGRACIONES DEL OPS (5.2): TechLog de tu avión y comprobación de PIREP
//  · TechLog (core/20-techlog.js): solo para tu vuelo («Mi callsign» de FSUIPC) y con el OPS abierto desde el
//    servidor local. Estado técnico en la tarjeta, TELEX «TECH STATUS» en el preflight, aviso si la librea
//    cargada no es la matrícula asignada, y la toma y los defectos del vuelo en el registro.
//  · PIREP (core/21-pirep.js): con phpVMS activado, cada pierna completada se contrasta con su PIREP.
// ══════════════════════════════════════════════════════════════════
let techlogLastAt = 0, techlogLastFlightAt = 0, pirepLastAt = 0;
const TECHLOG_EVERY = 60000, PIREP_EVERY = 120000;
const opsOwnCallsign = () => ($('fsuipcCs')?.value || '').trim().toUpperCase();

// Estado técnico de tu avión → tarjeta del vuelo (antes de generar los mensajes de la pasada)
async function opsTechlogTick(now) {
  if (!NBV.techlog.enabled()) return;
  if (!NBV.techlog.available()) { NBV.techlog.setStatus('Abre el OPS con START-ACARS en el PC del simulador para leer TechLog', false); return; }
  if (now - techlogLastAt < TECHLOG_EVERY) return;
  techlogLastAt = now;
  const cs = opsOwnCallsign(), flt = cs ? flights[cs] : null;
  try {
    const s = await NBV.techlog.snapshot();
    const nDef = s.deferred.length + s.open.length;
    NBV.techlog.setStatus(`Conectado · ${s.reg || 'sin avión'} · DISPATCH ${s.dispatch} · ${s.ready}${nDef ? ` · ${nDef} defecto(s)` : ''}${cs ? '' : ' · indica «Mi callsign» en FSUIPC'}`, true);
    if (!flt) return;
    const prev = flt.tech;
    flt.tech = s;
    const planned = String(flt.registration || '').toUpperCase().replace(/-/g, '');
    flt.techMismatch = !!(planned && s.reg && planned !== s.reg.replace(/-/g, ''));
    if (flt.techMismatch && !prev?.mismatchLogged) { log(`TechLog ${cs}: librea cargada ${s.reg}, avión asignado ${flt.registration}`, 'wrn'); s.mismatchLogged = true; }
    else if (prev?.mismatchLogged) s.mismatchLogged = true;
    if (prev && (prev.dispatch !== s.dispatch || prev.ready !== s.ready)) log(`TechLog ${cs}: DISPATCH ${s.dispatch} · ${s.ready}`, s.dispatch === 'GO' ? 'ops' : 'wrn');
  } catch (e) { NBV.techlog.setStatus(e.message, false); }
}

// TELEX «TECH STATUS» del preflight (solo tu vuelo y con TechLog accesible)
async function opsTechStatusMessage(flt) {
  if (!NBV.techlog.enabled() || !NBV.techlog.available() || flt.callsign !== opsOwnCallsign()) return null;
  const s = flt.tech || await NBV.techlog.snapshot();
  return { id: 'techlog', label: 'TECH STATUS', body: NBV.techlog.statusText(s, { cs: flt.callsign, plannedReg: flt.registration }) };
}

// Tras cada pasada: la toma y los defectos de tu vuelo (TechLog) y la comprobación de PIREP (phpVMS)
async function opsRegistroIntegraciones(now) {
  const recent = NBV.flightLog.list('', now).filter(e => now - (e.last || 0) < 24 * 3600000);
  const own = opsOwnCallsign();
  if (own && NBV.techlog.enabled() && NBV.techlog.available() && now - techlogLastFlightAt >= TECHLOG_EVERY) {
    const e = recent.find(x => x.cs === own && x.st === 'completado' && !x.tech?.closed);
    if (e) {
      techlogLastFlightAt = now;
      try {
        const rec = await NBV.techlog.flightFor(e);
        if (rec) {
          NBV.flightLog.annotate(e.id, { tech: rec }, now);
          if (rec.closed) log(`TechLog ${e.cs}: toma ${rec.landing ? rec.landing.vs + ' fpm' : '—'}${rec.defects.length ? ` · ${rec.defects.length} defecto(s) en vuelo` : ''}`, rec.defects.length ? 'wrn' : 'ops');
        }
      } catch (err) { /* TechLog cerrada: se reintenta en la siguiente pasada */ }
    }
  }
  if (!$('phpvmsEn')?.checked || now - pirepLastAt < PIREP_EVERY) return;
  pirepLastAt = now;
  for (const e of recent) {
    if (e.st !== 'completado' || e.pirep?.final) continue;
    let pirep = null;
    if (e.pirepId) { try { pirep = await NBV.pirepCheck.fetchPirep(phpvmsBase(), e.pirepId, await phpvmsHeaders()); } catch (err) { continue; } }
    const r = NBV.pirepCheck.evaluate(e, pirep, now);
    if (!r) continue;
    if (r.label !== e.pirep?.label || (r.issues || []).join() !== (e.pirep?.issues || []).join()) {
      if (r.level === 'wrn' || r.level === 'err') log(`PIREP ${e.cs} ${e.dep}→${e.arr}: ${r.label}${r.issues.length ? ' — ' + r.issues.join('; ') : ''}`, r.level === 'err' ? 'err' : 'wrn');
      else if (r.final) log(`PIREP ${e.cs} ${e.dep}→${e.arr}: ${r.label}`, 'ok');
    }
    NBV.flightLog.annotate(e.id, { pirep: { ...r, at: now } }, now);
  }
}

// «Preparar» un PIREP manual cuando vmsACARS no lo presentó: copia los datos y abre el formulario de phpVMS
async function flogPirepPrep(id) {
  const e = NBV.flightLog.list().find(x => x.id === id);
  if (!e) return;
  const text = NBV.pirepCheck.manualText(e);
  try { await navigator.clipboard.writeText(text); ss('ok', 'Datos del PIREP copiados: pégalos en el formulario de phpVMS'); }
  catch (err) { window.prompt('Copia estos datos para el PIREP manual:', text); }
  window.open(`${phpvmsBase()}/pireps/create`, '_blank', 'noopener');
}
